VALUES (646, '0', $t$ASK 646: the row names each judge of the order that was left out, and why$t$,
  $t$The row's line "[JUDGE ORDER v<n>: panel list ...; alternates list ... | SEATED: ...]" named who sat but not why the others did not: in run 42528 gemini, hydrogen, argon and neon are in the order and not seated, and the row gives no reason. Init Seats already records a reason for every seat it drops (__DROP) but output only the alternates' part, and Build Save Body read neither. Change, two nodes: Init Seats outputs seat_left_out, every order seat that was not seated, with its recorded reason; Build Save Body ends the JUDGE ORDER line with "; LEFT OUT: <seat> (<reason>), ..." or "; LEFT OUT: none". Expected effect: the row states why each judge of the order did not sit. Record only. Not changed: who sits, the AGREEMENT lines, alt_dropped and Format Markdown, reasoning, a model setting, a token limit, a prompt, what a seat is sent. (plan rev 0, heading 1 and 3, ask646/w4/plan646.md md5 f9052bc7)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it" at 08:25 CST 2026-11-25 on W4's card (Wall 12077; audit 42235 by W4's facts file), engine 8470161f to e11a57aa, after W1's recheck PASS of the rebased target b4 e27e24e5 (Wall 12076), and read back PASS by W1 (Wall 12078: live e11a57aa equals W1's rebuild in all 426 nodes and in the connections; t646 passes; standing 31 PASS 0 FAIL). Nothing was deleted and the seating is unchanged. IN PART, because no run has been made since the write. Offline (build b1, graded PASS by W1, Wall 12062): t646 29 pass 0 fail on the stored node outputs of each run; every old field of Init Seats is equal, and every order seat is seated or left out, never both. The 42528 line would read LEFT OUT: gemini, argon and neon (family google debates in this debate) and hydrogen and spark (is a debater). W1's N1 on the plan (Wall 12056) is met: a seat in both lists is listed once, and the reason "not reached" is dropped because it cannot occur. The written target is the fourth build of one unchanged build script: b1 on ee4e389d (dc3bedc6), b2 on the 641 fetch-back (764f434a), b3 (0ec564d1), b4 on the 645 fetch-back (e27e24e5); W4 found no W1 post naming b1, b2 or b3 by md5 (W1 graded b1 as "build b1" on Wall 12062). Note by W1: the replay covered the stored runs, not every pairing. NOT CHECKED by W1: the audit row. Open: two clean live runs.$t$,
  '12050, 12056, 12060, 12062, 12069, 12075, 12076, 12077, 12078, 12121, 12128, 12129, 12142',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo58Jbsg9gUqijyeXPR8zJryhd, "Write ASK 646 (the row names who was left out of the judge order and why)?"): he pressed "Write it" at 08:25 CST 2026-11-25. Card text, press and time are from W4's facts file; W3 did not read the card or the press. There was no build card: the build was offline files only, and the card came after the build grade.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 646 (the row names who was left out of the judge order and why)?", "options": {"Write it": "The JUDGE ORDER line ends with LEFT OUT and each seat's reason; Init Seats and Build Save Body change, seating does not.", "Hold": "Nothing is written; the row keeps naming only who sat."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58Jbsg9gUqijyeXPR8zJryhd", "press_time": "08:25 CST 2026-11-25", "message_above_the_card": "cmsg_017ZQamDMHrS6fqMHnQDVo58AWdUc4gbGEcBse2HWfAYZS", "source": "W4's facts file aar/w3/cards_641_to_652_from_w4.md; W3 did not read the card or the press."}$j$::jsonb,
  'W4',
  $j${"md5": "f9052bc754a35f2edf3d4d069202a823", "path": "ask646/w4/plan646.md", "note": "plan rev 0, graded PASS WITH N1 by W1 (Wall 12056); N1 met in the build (Wall 12062).", "source": "md5sum by W3; Wall 12056"}$j$::jsonb,
  $j$[{"path": "ask646/w4/b4/b646.cjs", "md5": "145e8e1868b22b3adb80c3f8aa2260a1", "what": "build script (the same file in b1 to b4)"}, {"path": "ask646/w4/b4/tg/target_engine_646.json", "md5": "e27e24e5dc0408fe210b281b2c0d01dd", "what": "target engine b4, on 8470161f (written)"}, {"path": "ask646/w4/b1/tg/target_engine_646.json", "md5": "dc3bedc60f0f2da76e46708063bc3568", "what": "target engine b1, on ee4e389d (not written)"}, {"path": "ask646/w4/b4/t646.cjs", "md5": "721f34bd10bb7ecff9f5f02239a13774", "what": "test"}, {"path": "ask646/w4/b4/out_t646.txt", "md5": "958f8bf18f497d171730aad2ad751339", "what": "test output"}, {"path": "ask646/w4/write/write646.sh", "md5": "d9ca233543cc7282b140357640937be0", "what": "write script"}, {"path": "ask646/w4/write/fetchback_eng_646.json", "md5": "a2c74e54a160caa3d5cdbc42b82855da", "what": "fetch-back after the write"}]$j$::jsonb,
  $j${"engine": "ask646/w4/write/revert_eng_646.json, md5 2712daa791d6fa8beba41ee1906d5218 (restores 8470161f)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12077; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (plan rev 0)", "wall_id": 12056, "md5_graded": "f9052bc7", "verdict_norm": "PASS", "source": "Wall 12056"}, {"seat": "W1", "verdict": "PASS (build b1)", "wall_id": 12062, "md5_graded": "dc3bedc6", "verdict_norm": "PASS", "source": "Wall 12062 (names \"build b1\"; the b1 target is dc3bedc6 by Wall 12060)"}, {"seat": "W1", "verdict": "PASS (recheck of b4; clear to write)", "wall_id": 12076, "md5_graded": "e27e24e5", "verdict_norm": "PASS", "source": "Wall 12076"}, {"seat": "W1", "verdict": "PASS (written target check with the full md5, made after the write: equal to live e11a57aa, 0 differences)", "wall_id": 12142, "md5_graded": "e27e24e5dc0408fe210b281b2c0d01dd", "verdict_norm": "PASS", "source": "Wall 12142"}]$j$::jsonb,
  ARRAY['e27e24e5dc0408fe210b281b2c0d01dd'], '[42235]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, nodes Init Seats and Build Save Body", "before": "version 8470161f; the JUDGE ORDER line names the order and who sat", "after": "version e11a57aa-f60d-4fee-8b59-22403aa8639e; Init Seats outputs seat_left_out (each order seat not seated, once, with its recorded reason) and the JUDGE ORDER line ends \"; LEFT OUT: <seat> (<reason>), ...\" or \"; LEFT OUT: none\", brackets removed; tagged ASK 646"}]$j$::jsonb,
  $j$[{"name": "t646.cjs on the build", "result": "29 pass, 0 fail: Init Seats old and new replayed on the stored node outputs of each run; every old field equal; 42528, 42517, 42373 and 42505 lines; C2 a seat that did not accept, brackets removed, \"none\"; C3 only the 2 nodes change, connections equal; C4 tag, no new catch", "source": "Wall 12060; reproduced by W1, Wall 12062, 12076, 12078"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), on the fetch-back (W4, Wall 12077) and on live (W1, Wall 12078); pair Library Check PASSES; reg385 PASS", "source": "Wall 12060, 12076, 12077, 12078"}, {"name": "NOT RUN", "result": "any live call; pairings other than the stored runs", "source": "Wall 12062"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (live e11a57aa equals W1's rebuild in all 426 nodes and in the connections; t646 passes; standing 31 PASS 0 FAIL). NOT CHECKED: the audit row.", "wall_id": 12078, "source": "Wall 12078"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "the row's JUDGE ORDER line ends with \"; LEFT OUT: ...\", naming every order seat that did not sit with its reason, or \"; LEFT OUT: none\"; the seating equals what the old engine would seat.", "not_shown": "the line on a live run's row.", "source": "Wall 12060, 12077"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN: part 10.0 version 332 (md5 c5e5a64c22f29578519422356e6a4873, 63,636 characters, log row 352), on the operator's press \"Write all six\" at 09:08 CST 2026-11-25 on W3's card (cmsg_017ZQamDMHrS6fqMHnQDVo589AHY4EW5dD8Zdyt26PvafU); audit 42303; pairs graded PASS by W1 (Wall 12121); read back PASS by W1 (Wall 12129)."}$j$::jsonb,
  'read back', $j$[12050, 12056, 12060, 12062, 12069, 12075, 12076, 12077, 12078, 12121, 12128, 12129, 12142]$j$::jsonb)
RETURNING id)
